/* Ver.0.3.3: clean TRY AGAIN animation */

.try-again-toast {

  width: 250px;

  height: 84px;

  background: transparent !important;

  overflow: visible;

}

.try-whole,

.try-piece {

  position: absolute;

  inset: 0;

  display: grid;

  place-items: center;

  border-radius: 20px;

  background: #673b39;

  color: #ffffff;

  font-weight: 1000;

  font-size: 1.42rem;

  letter-spacing: .03em;

  text-shadow: 0 2px 2px rgba(0,0,0,.24);

  box-shadow: 0 8px 22px rgba(77,43,40,.25);

}

.try-again-toast.show-whole .try-whole {

  animation: tryWholeIn .52s ease both;

}

.try-piece {

  border-radius: 0;

}

.try-left {

  clip-path: polygon(0 0, 51% 0, 51% 100%, 0 100%);

  animation: tryLeftFall .88s ease-in forwards;

}

.try-right {

  clip-path: polygon(49% 0, 100% 0, 100% 100%, 49% 100%);

  animation: tryRightFall .88s ease-in forwards;

}

.try-crack {

  position: absolute;

  left: 50%;

  top: 7px;

  width: 5px;

  height: 70px;

  transform: translateX(-50%);

  background: linear-gradient(165deg,

    transparent 0 7%,

    #f7dfcf 8% 18%,

    transparent 19% 27%,

    #f7dfcf 28% 43%,

    transparent 44% 53%,

    #f7dfcf 54% 70%,

    transparent 71% 79%,

    #f7dfcf 80% 93%,

    transparent 94% 100%);

  z-index: 3;

  animation: tryCrackFlash .28s ease-out forwards;

}

@keyframes tryWholeIn {

  0% { opacity: 0; transform: scale(.72) translateY(16px); }

  65% { opacity: 1; transform: scale(1.08) translateY(0); }

  100% { opacity: 1; transform: scale(1); }

}

@keyframes tryCrackFlash {

  0% { opacity: 0; }

  100% { opacity: 1; }

}

@keyframes tryLeftFall {

  0% { opacity: 1; transform: translate(0,0) rotate(0); }

  18% { transform: translate(-4px,2px) rotate(-2deg); }

  100% { opacity: 0; transform: translate(-105px,70px) rotate(-24deg); }

}

@keyframes tryRightFall {

  0% { opacity: 1; transform: translate(0,0) rotate(0); }

  18% { transform: translate(4px,2px) rotate(2deg); }

  100% { opacity: 0; transform: translate(105px,70px) rotate(24deg); }

}





/* Ver.0.3.4: swipe-to-mark and unified soft X */

.board {

  touch-action: none;

  overscroll-behavior: contain;

}

.tile {

  -webkit-tap-highlight-color: transparent;

}

.mark-x {

  position: relative;

  display: block;

  width: 76%;

  height: 76%;

  font-size: 0 !important;

  -webkit-text-stroke: 0 !important;

  text-shadow: none !important;

  filter: drop-shadow(0 2px 2px rgba(0,0,0,.24));

}

/* Dark outer X */

.mark-x::before {

  content: "";

  position: absolute;

  inset: 3%;

  background: #4f4641;

  clip-path: polygon(18% 8%,50% 40%,82% 8%,92% 18%,60% 50%,92% 82%,82% 92%,50% 60%,18% 92%,8% 82%,40% 50%,8% 18%);

  border-radius: 24%;

}

/* One continuous white X, so the center never looks like overlapping bandages */

.mark-x::after {

  content: "";

  position: absolute;

  inset: 10%;

  background: #fffdf8;

  clip-path: polygon(18% 8%,50% 40%,82% 8%,92% 18%,60% 50%,92% 82%,82% 92%,50% 60%,18% 92%,8% 82%,40% 50%,8% 18%);

  border-radius: 26%;

}



