/* Ver.0.8.39: stronger board mark visibility */

/* Existing SVG geometry and tile hit targets remain unchanged. */

.tile > .mark-symbol .mark-outline{stroke:rgba(64,53,59,.50)!important;stroke-width:16!important}

.tile > .mark-symbol .mark-core{stroke:#fff!important;stroke-width:11.5!important}

