#modeCycle .mark-symbol .mark-core{stroke-width:11.5!important}

#modeCycle .mark-symbol.mark-x .mark-outline{stroke-width:18!important}

#modeCycle .mark-symbol.mark-x .mark-core{stroke-width:13!important}

/* End Ver.0.8.39 */
/* Ver.0.8.41: keep the question mark dot visually separated. */
.tile > .mark-symbol.mark-q .mark-outline{stroke-width:11!important}
.tile > .mark-symbol.mark-q .mark-core{stroke-width:7.5!important}
