#modeCycle .mark-symbol.mark-q .mark-core{stroke-width:7.5!important}
/* End Ver.0.8.41 */



/* Ver.0.8.43: visually align X, triangle, and question marks. */
/* X remains the approved reference. */
.tile > .mark-symbol.mark-t{width:92%!important;height:92%!important}
.tile > .mark-symbol.mark-t .mark-outline{stroke-width:18!important}
.tile > .mark-symbol.mark-t .mark-core{stroke-width:13!important}
.tile > .mark-symbol.mark-q{width:88%!important;height:88%!important}
