.tile > .mark-symbol.mark-q .mark-core{stroke-width:11.5!important}
#modeCycle .mark-symbol.mark-t .mark-outline{stroke-width:18!important}
#modeCycle .mark-symbol.mark-t .mark-core{stroke-width:13!important}
#modeCycle .mark-symbol.mark-q .mark-outline{stroke-width:16!important}
#modeCycle .mark-symbol.mark-q .mark-core{stroke-width:11.5!important}
