.tile > .mark-symbol.mark-t{width:96%!important;height:96%!important}
.tile > .mark-symbol.mark-t .mark-outline{stroke-width:18!important}
.tile > .mark-symbol.mark-t .mark-core{stroke-width:13!important}
.tile > .mark-symbol.mark-q .mark-outline{stroke-width:18!important}
