#modeCycle .mark-symbol.mark-q .mark-outline{stroke-width:18!important}
#modeCycle .mark-symbol.mark-q .mark-core{stroke-width:13!important}
/* End Ver.0.8.51 */


/* Ver.0.8.53: isolate MARK button icon geometry from board geometry. */
/* Board marker geometry remains frozen; only the compact mode button is normalized. */
#modeCycle{
  overflow:hidden!important;
  position:relative!important;
